sp_widget.client_script:
api.controller = function() {
    var c = this;

    if (c.data.movie.hasUserRating) {
        c.data.selectedRating = c.data.movie.currentUserRating;
    }

    c.saveRating = function() {

        if (!c.data.selectedRating) {
            alert('nevybral si rating')
            return;
        }
        c.server.get({
                action: "saveRating",
                rating: c.data.selectedRating
            })
            .then(function(response) {
                location.reload();
            });
    };
};

sp_widget.css:
/* Malý poster – ako v Table Search */
.movie-poster img {
    width: 150px;      /* nastavíš podľa potreby */
    height: auto;       /* zachová proporcie */
    border-radius: 6px; /* pekný zaoblený roh */
    box-shadow: 0 2px 6px rgba(0,0,0,0.3); /* jemný tieň */
    display: block;
    margin: 0 auto;    /* centrovanie v kolónke */
}

/* Odstrániť pôvodný hero styling */
.movie-poster-tmdb {
    display: none !important;
}

.movie-cast-section {
    margin-top: 20px;
}

.movie-cast-list {
    display: flex;
    gap: 16px;
    overflow-x: auto;
    padding-bottom: 10px;
}

.movie-cast-card {
    min-width: 140px;
    max-width: 140px;
    border: 1px solid #ddd;
    border-radius: 8px;
    overflow: hidden;
    background: #fff;
    flex-shrink: 0;
}

.movie-cast-card img {
    width: 100%;
    height: 180px;
    object-fit: cover;
    display: block;
}

.movie-cast-info {
    padding: 10px;
}

.movie-cast-name {
    font-weight: 600;
    margin-bottom: 6px;
}

.movie-cast-role {
    font-size: 13px;
    color: #666;
}

.movie-crew-section {
    display: flex;
    gap: 40px;
    margin: 20px 0;
    flex-wrap: wrap;
}

.movie-crew-name {
    font-weight: 600;
}

.movie-crew-role {
    font-size: 13px;
    color: #666;
}

sp_widget.script:
(function() {

    var sysId = $sp.getParameter('sys_id');
    if (!sysId)
        return;

    var movieGr = new GlideRecord('x_1080820_mvx_movie');
    if (!movieGr.get(sysId))
        return;

    var userId = gs.getUserID();
    var userName = gs.getUserName();

    data.movie = {
        title: movieGr.getValue('title'),
        originalTitle: movieGr.getValue('original_title'),
        festivalTitle: movieGr.getValue('festival_title'),
        releaseDate: movieGr.getValue('release_date'),
        description: movieGr.getValue('description'),
        posterUrl: movieGr.getValue('poster_url'),
        tmdbId: movieGr.getValue('tmdb_id'),
        genres: [],
        actors: [],
        directors: [],
        averageRating: 0,
        ratingCount: 0,
        currentUserRating: '',
        hasUserRating: false,
        isLoggedIn: userName !== 'guest',
        currentReviewId: ''
    };

    function getUserReview(movieId, userId) {
        var reviewGr = new GlideRecord('x_1080820_mvx_review');
        reviewGr.addQuery('movie_ref', movieId);
        reviewGr.addQuery('user_ref', userId);
        reviewGr.query();

        if (reviewGr.next()) {
            return {
                rating: parseInt(reviewGr.getValue('rating'), 10),
                reviewId: reviewGr.getValue('sys_id')
            };
        }

        return null;
    }

    function saveRating(movieId, userId, rating) {
        var reviewGr = new GlideRecord('x_1080820_mvx_review');
        reviewGr.addQuery('movie_ref', movieId);	//('movie_ref', sysId)
        reviewGr.addQuery('user_ref', userId);
        reviewGr.query();

        if (reviewGr.next()) {
            reviewGr.setValue('rating', rating);
            reviewGr.update();
        } else {
            reviewGr.initialize();
            reviewGr.setValue('movie_ref', movieId);	//('movie_ref', sysId)
            reviewGr.setValue('user_ref', userId);
            reviewGr.setValue('rating', rating);
            reviewGr.insert();
        }
    }

    function getRelatedRecordsByMovie(table, transformFunction, targetArray) {
        var relatedGr = new GlideRecord(table);
        relatedGr.addQuery('movie_ref', sysId);
        relatedGr.query();

        while (relatedGr.next()) {
            targetArray.push(transformFunction(relatedGr));
        }
    }

    function getAverageRating(movieId) {
        var reviewGr = new GlideRecord('x_1080820_mvx_review');
        reviewGr.addQuery('movie_ref', movieId);
        reviewGr.query();

        var result = {
            ratingSum: 0,
            ratingCount: 0,
            averageRating: 0
        };

        while (reviewGr.next()) {
            var rating = parseInt(reviewGr.getValue('rating'), 10);
            result.ratingSum += rating;
            result.ratingCount++;
        }

        if (result.ratingCount > 0) {
            result.averageRating = (result.ratingSum / result.ratingCount).toFixed(1);
        }

        return result;
    }

    if (input && input.action == 'saveRating' && data.movie.isLoggedIn) {
        saveRating(sysId, userId, input.rating);
    }

    getRelatedRecordsByMovie(
        'x_1080820_mvx_movie_actor',
        function(gr) {
            return {
                name: gr.getDisplayValue('actor_ref'),
                role: gr.getValue('role_name'),
                photo: gr.actor_ref.profile_url + ''
            };
        },
        data.movie.actors
    );

    getRelatedRecordsByMovie(
        'x_1080820_mvx_movie_genre',
        function(gr) {
            return gr.getDisplayValue('genre_ref');
        },
        data.movie.genres
    );

    getRelatedRecordsByMovie(
        'x_1080820_mvx_movie_director',
        function(gr) {
            return {
                name: gr.getDisplayValue('director_ref')
            };
        },
        data.movie.directors
    );

    var ratingInfo = getAverageRating(sysId);
    data.movie.averageRating = ratingInfo.averageRating;
    data.movie.ratingCount = ratingInfo.ratingCount;

    if (data.movie.isLoggedIn) {
        var userReview = getUserReview(sysId, userId);

        if (userReview) {
            data.movie.hasUserRating = true;
            data.movie.currentUserRating = userReview.rating;
            data.movie.currentReviewId = userReview.reviewId;
        }
    }
})();

